"""Explain further text for the questions of the charged-particle interactions chapter (charged-particles). Entries are registered with q() from more_content."""
from more_content import q
import charged_particles as X          # the chapter's constants, so that the numbers in an explanation match the chapter

T = "charged-particles"
H_ = "How to decide"

q(T, "A 6 MeV electron slows down in water.",
  simple="A delta ray is an electron knocked out of an atom with so much energy that it travels away and ionizes along a track of its own. Only a close, head-on kind of encounter with a single atomic electron can hand over that much energy at once.",
  steps=["Rule: the product must be a fast secondary electron, so the interaction must give one atomic electron a large energy.",
         "Hard collision: one electron at close range receives up to half the energy of the incident electron, enough to form a track.",
         "Soft collision: the atom as a whole takes a few to tens of eV; the electron it may release stays close to the track.",
         "Elastic scattering by a nucleus: a change of direction, almost no energy given to anything.",
         "Bremsstrahlung: the energy leaves as a photon, not as an electron."],
  tip="Delta rays are rare compared with soft collisions, yet hard and soft collisions carry roughly equal shares of the collision loss, because each hard collision transfers so much more.",
  how=H_)
q(T, "Stopping powers of electrons are tabulated for water, bone, and lead.",
  simple="A stopping power is energy lost per unit length of path. Dividing by the density turns centimetres of material into grams per square centimetre, so the mass stopping power is energy per (g/cm²), written MeV cm²/g. In that form water vapour and liquid water, or lung and muscle, have nearly the same value.",
  steps=["Linear stopping power S: MeV per cm of path.",
         "Density ρ: g/cm³.",
         "S/ρ = (MeV/cm) / (g/cm³) = MeV cm²/g.",
         "MeV/cm is the linear form; cm²/g has no energy in it and is the unit of μ/ρ; MeV/g is energy per mass, the form of a dose."],
  tip="Mass stopping power and mass attenuation coefficient share the cm²/g part, but only the stopping power carries an energy, because it is a rate of energy loss rather than a probability of interaction.",
  how=H_)
q(T, "A 9 MeV electron crosses a slab of cortical bone.",
  simple="Over a slab thin enough that the electron's energy changes little, the energy lost is the stopping power times the path. The mass stopping power has to be multiplied by the density first to give MeV per centimetre, and bone is almost twice as dense as water.",
  steps=[f"Linear stopping power: S = (S/ρ) × ρ = {X.S6:.1f} × {X.RHO6:.2f} = {X.q_bone_cm:.3f} MeV/cm.",
         f"Energy lost: ΔE = {X.q_bone_cm:.3f} MeV/cm × {X.TH6:.2f} cm = {X.q_bone:.2f} MeV.",
         f"Check in mass thickness: {X.RHO6:.2f} × {X.TH6:.2f} = {X.RHO6 * X.TH6:.3f} g/cm², and {X.S6:.1f} × {X.RHO6 * X.TH6:.3f} = {X.q_bone:.2f} MeV.",
         f"The electron leaves with about {X.T6 - X.q_bone:.1f} MeV, so the stopping power has changed little across the slab and the thin-layer form holds."],
  tip=f"Forgetting the density gives {X.q_bone_nr:.2f} MeV, the loss in 0.60 cm of a material with the density of water.",
  check=X.q_bone)
q(T, "Electrons of 1 MeV slow down in lead and in water.",
  simple="Collision losses come from atomic electrons, so the loss per gram depends on how many electrons a gram holds and how easily they take up energy. Lead has about 0.40 electrons per nucleon against 0.555 in water, whose hydrogen adds one electron for each nucleon, and lead's tightly bound electrons raise the mean excitation energy, which lowers the logarithm in the stopping power.",
  steps=["Rule: S<sub>col</sub>/ρ ∝ (Z/A) × [a logarithm that falls slowly as I rises].",
         f"Electrons per gram: 0.40 / 0.555 = {0.40 / 0.555:.2f} of water's.",
         "Mean excitation energy: 823 eV against 75 eV, a further reduction of the logarithm.",
         "Together these give about half of water's value at 1 MeV.",
         "Density does not enter a mass stopping power, and the radiative loss is a separate part of the total."],
  tip="Per centimetre the order reverses: lead is about 11 times denser than water, so a centimetre of lead stops an electron far faster than a centimetre of water.",
  how=H_)
q(T, "A 20 MeV electron slows down in water.",
  simple="The rule gives the radiative loss as a multiple of the collision loss. The question asks for the radiative part of the whole loss, so the ratio has to be turned into a share of the sum.",
  steps=[f"Ratio: r = Z T / 800 = {X.Z_WATER} × 20 / 800 = {X.q_share_r / 100:.3f}.",
         f"Total in units of the collision loss: 1 + r = {1 + X.q_share_r / 100:.3f}.",
         f"Radiative share: r / (1 + r) = {X.q_share_r / 100:.3f} / {1 + X.q_share_r / 100:.3f} = {X.q_share / 100:.4f}, or {X.q_share:.1f}%.",
         f"At 10 MeV the same rule gives {100 * X.s_w10:.1f}%, so the share roughly doubles as the energy doubles while it is small."],
  tip=f"Reporting r itself as the share gives {X.q_share_r:.1f}%. The difference grows as r grows: in tungsten at 20 MeV r is above 1, and a share can never exceed 100%.",
  check=X.q_share)
q(T, "A vial of Y-90, a pure β emitter",
  simple="A β particle that stops in a high-Z material turns much more of its energy into bremsstrahlung, and those photons go through a thin shield easily. Stopping the β particles first in a low-Z plastic makes few photons; a lead layer outside then attenuates the few that are made.",
  steps=["Rule: the radiative share rises about in proportion to Z.",
         f"Lead against acrylic: {X.Z_LEAD} / {X.Z_ACRYL} = {X.pb_acryl:.1f}, so about {X.pb_acryl:.0f} times more bremsstrahlung per unit of collision loss in lead.",
         "Acrylic first: the β particles stop with little radiation.",
         "Lead outside: attenuates the photons that are made; it is not struck by β particles.",
         "Lead or tungsten next to the vial: the β particles stop in high-Z metal, making the most bremsstrahlung."],
  tip="Tungsten stops the β particles in a shorter distance, but the thickness that stops them is not the problem; the photons it makes are.",
  how=H_)
q(T, "For a 10 MeV electron in water, the restricted collision stopping power",
  simple="The collision stopping power counts every collision. The restricted one keeps only collisions that leave their energy near the track, so the energy that energetic delta rays carry away along their own tracks is left out. For a 10 MeV electron that removed part is a sizeable fraction.",
  steps=[f"Energy carried by delta rays above 10 keV at 10 MeV (cross section for collisions between free electrons): {X.h10:.2f} MeV cm²/g.",
         f"Share of S<sub>col</sub>: {X.h10:.2f} / {X.SCOL10:.2f} = {100 * X.fr10:.0f}%.",
         f"Remaining: L<sub>10 keV</sub>/ρ = {X.SCOL10:.2f} − {X.h10:.2f} = {X.l10:.2f} MeV cm²/g.",
         "Soft collisions, excitation and ionization alike, are counted in both quantities, and both are losses per unit path."],
  tip=f"The removed part grows with energy, because a faster electron can give more to one delta ray: at 1 MeV it is {X.hard_loss(1, 0.010):.2f} MeV cm²/g, at 20 MeV {X.hard_loss(20, 0.010):.2f} MeV cm²/g.",
  how=H_)
q(T, "A 1 MeV electron slows down in water.",
  simple="LET is a stopping power quoted per micrometre of track, the scale of a cell. With no cutoff it equals the collision stopping power, so only a change of units is needed.",
  steps=[f"Linear collision stopping power: {X.SCOL1:.2f} MeV cm²/g × 1.00 g/cm³ = {X.SCOL1:.2f} MeV/cm.",
         "1 MeV = 1000 keV and 1 cm = 10,000 µm, so 1 MeV/cm = 0.1 keV/µm.",
         f"LET = {X.SCOL1:.2f} × 0.1 = {X.q_let1:.3f} keV/µm."],
  tip=f"Reading MeV/cm as keV/µm gives {X.SCOL1:.2f} keV/µm, ten times too high. Electrons stay near 0.2 keV/µm at therapy energies, a low LET; α particles of a few MeV are near 100 keV/µm.",
  check=X.q_let1)
q(T, "A narrow beam of 10 MeV electrons enters water, where their CSDA range",
  simple="The CSDA range measures how long the path is, not how deep it goes. An electron is light, so the nuclei it passes deflect it again and again, and its path zigzags. The deepest point along the beam direction lies short of the full length of the path.",
  steps=["Rule: CSDA range = ∫ dT / (S/ρ), the mean length of the path.",
         "Multiple scattering: each deflection turns part of the path sideways or backward, so depth gained is less than path travelled.",
         "Straggling: spreads the path lengths above and below the mean, so it cannot shorten every one.",
         "The CSDA range starts where the electron enters, and it uses the total stopping power, with hard collisions included."],
  tip="For protons the path is nearly straight, so their mean depth of penetration is almost equal to the CSDA range; the gap between path and depth is an electron effect.",
  how=H_)
q(T, "A narrow electron beam passes through a thin foil.",
  simple="Each nucleus the electron passes deflects it a little, in a random direction, so the deflections add up like a random walk: the mean square angle grows with the number of nuclei passed, that is with the path, and is larger when each nucleus pulls harder (higher Z) or the electron is slower (lower energy).",
  steps=["Thickness: more nuclei along the path, so a larger mean square angle, in proportion to the path in a thin layer.",
         "Atomic number: per atom the deflection grows about as Z², per gram about as Z, so a higher-Z foil of the same mass thickness scatters more.",
         "Energy: the mean square angle falls about as 1/(pv)², with p the momentum and v the speed, so a lower energy scatters more.",
         "Beam current: more electrons, each deflected by the same amount."],
  tip="A higher-Z foil of the same mass thickness scatters more for about the same energy loss, which is why thin high-Z foils spread linac electron beams.",
  how=H_)
q(T, "An α particle and a proton enter water with the same speed.",
  simple="The stopping power of a heavy particle depends on its charge and its speed, not on its mass. At the same speed the doubly charged α particle loses energy four times as fast. But it carries about four times the kinetic energy, so it travels about as far.",
  steps=["Bethe: S<sub>col</sub> ∝ z²/v² times a slowly varying logarithm of the speed.",
         "Same speed, z = 2 against 1: stopping power ratio 2² = 4.",
         f"Same speed, mass {X.MALPHA:.0f} against {X.MP:.0f} MeV: kinetic energy ratio {X.MALPHA / X.MP:.2f}.",
         f"Range ∝ M/z² at a given speed: ({X.MALPHA:.0f}/4) / {X.MP:.0f} = {X.r_ap:.3f}, about the same range."],
  tip="A quarter of the range would follow from the stopping power alone, forgetting that the α particle starts with about four times the energy.",
  how=H_)
q(T, "Several quantities describe how charged particles lose energy.",
  simple="Two of these are rates at one energy (the collision stopping power and its restricted part), two follow the electron over its whole slowing-down (the radiation yield and the CSDA range), and one is a single energy for a material (the critical energy).",
  steps=["Mass collision stopping power: energy lost to atomic electrons per g/cm², at one energy.",
         "Restricted collision stopping power: the same, keeping only energy transfers below a cutoff Δ.",
         "Radiation yield: the fraction of the starting kinetic energy radiated as bremsstrahlung by the time the electron stops.",
         "CSDA range: the mean path length when energy is lost continuously at the total stopping power.",
         f"Critical energy: where S<sub>rad</sub> = S<sub>col</sub>, about 800/Z MeV, {X.ec_pb:.1f} MeV for lead by the rule."],
  tip=f"The radiation yield is smaller than the radiative share at the starting energy, because the share falls as the electron slows: by the rule about {100 * X.y_w10:.0f}% for a 10 MeV electron in water against a starting share of {100 * X.s_w10:.0f}%.",
  how=H_)
